// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of [http.ServeMux].
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	http.Handler
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/users", wrapper.RegisterUser)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/users/me", wrapper.GetCurrentUser)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/sessions", wrapper.CreateSession)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/api/v1/sessions/current", wrapper.DeleteCurrentSession)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/albums", wrapper.ListAlbums)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/albums", wrapper.CreateAlbum)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/api/v1/albums/{albumId}", wrapper.DeleteAlbum)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/albums/{albumId}", wrapper.GetAlbum)
	m.HandleFunc(http.MethodPatch+" "+options.BaseURL+"/api/v1/albums/{albumId}", wrapper.UpdateAlbum)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/albums/{albumId}/reviews", wrapper.ListReviews)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/albums/{albumId}/reviews", wrapper.CreateReview)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/api/v1/albums/{albumId}/reviews/{reviewId}", wrapper.DeleteReview)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/albums/{albumId}/reviews/{reviewId}", wrapper.GetReview)
	m.HandleFunc(http.MethodPatch+" "+options.BaseURL+"/api/v1/albums/{albumId}/reviews/{reviewId}", wrapper.UpdateReview)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/health/live", wrapper.GetLiveness)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/health/ready", wrapper.GetReadiness)

	return m
}

